(window.LMP_I18N = window.LMP_I18N || {})["vi"] = {"cap.think":"Đang suy nghĩ","cap.think.body":"Suy luận từng bước trước khi trả lời. Giỏi hơn về toán, logic và lập kế hoạch — bạn có thể đọc suy nghĩ của nó.","cap.tools":"Công cụ","cap.tools.body":"Có thể chạy JavaScript, tìm kiếm trên web hoặc đọc một trang ngay giữa câu trả lời — chỉ khi bạn bật công cụ.","cap.vision":"Thị giác","cap.vision.body":"Hiểu được ảnh. Một tiện ích hình ảnh nhỏ được tự động tải xuống cùng mô hình.","card.branch":"<b>Đổi ý thoải mái.</b> Sửa tin nhắn, tạo lại câu trả lời hoặc phân nhánh sang cuộc trò chuyện mới mà không phải bắt đầu lại.","card.branch.a1":"Lá phong buông cành…","card.branch.a2":"Mưa lạnh trên mặt hồ…","card.branch.q":"Viết một bài haiku về mùa thu.","card.branch.tag":"↳ Đã phân nhánh sang cuộc trò chuyện mới","card.docs":"<b>Hỏi tài liệu của bạn.</b> PDF, Word, EPUB hoặc Markdown — tìm theo ý nghĩa, trả lời từ đúng đoạn cần thiết.","card.docs.a":"Với <b>thông báo bằng văn bản trước 60 ngày</b>, sau sáu tháng đầu. <span class=\"muted\">— Điều 8</span>","card.docs.indexed":"đã lập chỉ mục","card.docs.q":"Khi nào tôi có thể chấm dứt hợp đồng thuê?","card.prompts":"<b>Đặt vai trò một lần.</b> Lưu lời nhắc hệ thống — một nhân vật, một giọng điệu, một định dạng — và dùng lại với bất kỳ mô hình nào.","card.prompts.p1":"Ngắn gọn · trả lời bằng tiếng Pháp","card.prompts.p2":"Người review Kotlin cấp cao","card.prompts.p3":"Giải thích như cho trẻ lên năm","card.tools":"<b>Để nó hành động.</b> Các mô hình đủ khả năng có thể chạy JavaScript, tìm kiếm trên web hoặc đọc một trang ngay khi đang trả lời.","card.tools.off":"Mặc định tắt","card.tools.results":"5 kết quả","card.vision":"<b>Cho nó xem ảnh.</b> Chụp hoặc chọn một ảnh rồi hỏi về nó — đọc chữ, mô tả khung cảnh, nhận diện đồ vật.","card.vision.a":"Một chú cừu lông xù đang gặm cỏ trên đồng cỏ xanh vào một ngày nắng.","card.vision.alt":"Một chú cừu đang gặm cỏ trên cánh đồng","card.voice":"<b>Nói thay vì gõ.</b> Chữ hiện ra ngay khi bạn nói, hỗ trợ 35 ngôn ngữ. Nhận dạng chạy ngoại tuyến.","card.voice.q":"Lên kế hoạch chuyến đi ba ngày đến Lisbon với cà phê ngon và…","control.body1":"<b>Kéo thanh trượt và xem câu trả lời thay đổi.</b> Nhiệt độ quyết định mô hình táo bạo đến đâu — thấp cho dữ kiện và code, cao cho động não ý tưởng.","control.body2":"Top‑P, Top‑K, Min‑P, phạt lặp lại, hạt giống và kích thước ngữ cảnh cũng đều có, và mỗi mô hình ghi nhớ cài đặt riêng của nó.","control.eyebrow":"Kiểm soát","control.title":"Tinh chỉnh cá tính.","cta.body":"Vài giây để cài đặt. Vài phút để tải mô hình. Sau đó, tạm biệt đám mây.","cta.source":"Xem mã nguồn trên GitHub","cta.title":"Mọi mô hình.<br/>Trong túi bạn.","faq.a1":"LM Playground cho phép bạn chạy các mô hình ngôn ngữ lớn trực tiếp trên thiết bị Android, iPhone hoặc iPad của bạn. Toàn bộ quá trình xử lý diễn ra cục bộ – không cần máy chủ đám mây.","faq.a10":"**iPhone & iPad:** Vào Cài đặt, rồi Mô hình. Vuốt sang trái trên mô hình đã tải và chạm vào Xóa.\n**Android:** Vào Cài đặt, sau đó Mô hình. Trong phần “Đã tải”, nhấn vào biểu tượng xóa bên cạnh mô hình bạn muốn gỡ bỏ.","faq.a11":"Lời nhắc hệ thống là một chỉ dẫn có thể tái sử dụng, định hình cách mô hình phản hồi — ví dụ: “Bạn là một gia sư khoa học súc tích. Hãy giải thích các ý tưởng một cách rõ ràng bằng những ví dụ thường ngày” hoặc “Bạn là một người đánh giá mã cấp cao. Hãy chỉ ra lỗi, các trường hợp biên và vấn đề bảo mật”. Tạo và quản lý chúng trong Cài đặt → Lời nhắc hệ thống, rồi áp dụng một lời nhắc cho cuộc trò chuyện của bạn. Chúng được lưu trên thiết bị của bạn và chỉ được gửi đến mô hình cục bộ.","faq.a12":"Công cụ cho phép các mô hình đủ khả năng thực hiện hành động trong khi trả lời. Có ba công cụ: Chạy JavaScript (tính toán, ngày tháng và xử lý văn bản trong môi trường cách ly trên thiết bị), Tìm kiếm web (tìm thông tin mới nhất trên web), và Tải trang web (đọc một trang để mô hình có thể tóm tắt hoặc trích dẫn). Bật chúng trong Cài đặt → Công cụ. Mỗi công cụ đều tắt theo mặc định và chỉ hoạt động với các mô hình hỗ trợ gọi công cụ — hãy tìm huy hiệu hình búa trong trình chọn mô hình.","faq.a13":"Chỉ khi bạn bật chúng. Tìm kiếm web gửi truy vấn của mô hình đến DuckDuckGo, và Tải trang web tải xuống các trang mà mô hình chọn mở — những yêu cầu đó đi đến chính các trang web, không phải đến nhà phát triển. Chạy JavaScript vẫn hoàn toàn nằm trên thiết bị của bạn và không có truy cập internet. Khi tất cả công cụ đều tắt (mặc định), không có gì rời khỏi thiết bị của bạn. Xem Chính sách Bảo mật để biết chi tiết.","faq.a14":"**iPhone & iPad:** Không. iOS không cho ứng dụng dùng GPU khi chạy nền, nên câu trả lời sẽ dừng khi bạn chuyển sang ứng dụng khác. Phần đã viết được giữ lại, và nút Tiếp tục sẽ hoàn tất khi bạn quay lại.\n**Android:** Có. Khi ứng dụng chạy nền, một thông báo sẽ theo dõi trạng thái của mô hình — đã tải, đang tạo, rồi phản hồi đã sẵn sàng — và cho phép bạn sao chép hoặc chia sẻ câu trả lời. Bạn cũng có thể bật âm báo hoàn tất ngắn trong Cài đặt → Âm thanh và Rung. Các bản tải mô hình hiển thị thông báo tiến trình riêng với tốc độ và thời gian dự kiến.","faq.a15":"Không. Chạm vào micrô trong ô tin nhắn và nói — một mô hình nhận dạng giọng nói chuyển lời của bạn thành văn bản ngay trên điện thoại khi bạn nói, với 35 ngôn ngữ. Âm thanh không bao giờ được lưu hay gửi đi đâu, nên tính năng đọc chính tả hoạt động hoàn toàn ngoại tuyến. Mô hình (718 MB) chỉ tải về một lần, vào lần đầu bạn dùng micrô.","faq.a2":"Ứng dụng hỗ trợ các mô hình định dạng GGUF với lượng tử hóa Q4_K_M, bao gồm Qwen 3, Gemma 3, Llama 3.2, Phi‑4 mini và DeepSeek R1 Distill với nhiều kích thước khác nhau.","faq.a3":"Kích thước mô hình từ khoảng 500 MB (mô hình nhỏ như Qwen 3 0.6B) đến vài GB (mô hình lớn hơn như DeepSeek R1 7B). Hãy đảm bảo bạn có đủ dung lượng trống trước khi tải xuống.","faq.a4":"Internet cần thiết để tải xuống các mô hình, và — nếu bạn bật chúng — cho các công cụ web tùy chọn (tìm kiếm web và tải trang). Ngoài ra, một khi mô hình đã được tải xuống, nó chạy hoàn toàn ngoại tuyến trên thiết bị của bạn.","faq.a5":"Các cuộc trò chuyện của bạn được xử lý cục bộ trên thiết bị và không bao giờ được ứng dụng gửi đến máy chủ. Ngoại lệ duy nhất là các công cụ web tùy chọn: nếu bạn bật tìm kiếm web hoặc tải trang, các truy vấn tìm kiếm của mô hình và các trang nó mở sẽ được gửi đến những trang web đó (tìm kiếm sử dụng DuckDuckGo). Các công cụ được tắt theo mặc định, vì vậy không có gì rời khỏi thiết bị của bạn trừ khi bạn bật chúng. Xem Chính sách Bảo mật để biết chi tiết.","faq.a6":"Mô hình lớn hơn cần nhiều thời gian hơn để tải vào bộ nhớ. Thời gian tải phụ thuộc vào phần cứng thiết bị của bạn. Sau khi tải, mô hình sẽ nằm trong bộ nhớ cho đến khi bạn gỡ nó.","faq.a7":"Thiết bị có nhiều RAM hơn có thể chạy mô hình lớn hơn. Để đạt hiệu suất tốt nhất, hãy sử dụng thiết bị có ít nhất 6 GB RAM cho mô hình nhỏ và 8+ GB cho mô hình lớn hơn.","faq.a8":"**iPhone & iPad:** Có. Trong Cài đặt → Mô hình, chạm Nhập và chọn tệp .gguf, hoặc sao chép tệp vào thư mục Models của LM Playground trong ứng dụng Tệp. Ứng dụng sẽ tự nhận và hiển thị cùng danh mục có sẵn. Mẫu trò chuyện và cài đặt tokenizer được đọc từ siêu dữ liệu GGUF. Nếu một mô hình cụ thể không hoạt động, vui lòng mở issue trên GitHub.\n**Android:** Có. Đặt tệp .gguf của bạn vào thư mục lưu trữ đã chọn trong Cài đặt → Mô hình (cùng thư mục được dùng cho các bản tải về). Ứng dụng sẽ tự động nhận diện và hiển thị nó trong trình chọn mô hình cùng với danh mục tích hợp sẵn. Cài đặt mẫu cuộc trò chuyện và tokenizer được đọc từ metadata của tệp GGUF. Nếu một mô hình cụ thể không hoạt động, vui lòng mở issue trên GitHub.","faq.a9":"**iPhone & iPad:** Trong thư mục Models của LM Playground, bạn có thể thấy thư mục này trong ứng dụng Tệp và trong Finder khi thiết bị kết nối với máy Mac.\n**Android:** Có. Vào Cài đặt, sau đó Mô hình, và sử dụng tùy chọn “Đổi thư mục” để chọn vị trí lưu trữ khác.","faq.ios.a":"Sắp ra mắt trên App Store. LM Playground cho iOS sẽ cần iOS 26 trở lên và iPhone 15 Pro trở lên, hoặc iPad dùng chip M1 trở lên. Trò chuyện, nhận diện hình ảnh, tài liệu, đọc chính tả và công cụ đều chạy trên thiết bị của bạn, giống như trên Android.","faq.ios.q":"LM Playground có dùng được trên iPhone và iPad không?","faq.q1":"LM Playground là gì?","faq.q10":"Làm sao để xóa mô hình?","faq.q11":"Lời nhắc hệ thống là gì?","faq.q12":"Công cụ là gì và có những công cụ nào?","faq.q13":"Các công cụ web có gửi dữ liệu của tôi lên mạng không?","faq.q14":"Ứng dụng có thông báo cho tôi khi phản hồi sẵn sàng không?","faq.q15":"Tính năng đọc chính tả có gửi giọng nói của tôi đi đâu không?","faq.q2":"Những mô hình nào được hỗ trợ?","faq.q3":"Tôi cần bao nhiêu dung lượng lưu trữ?","faq.q4":"Ứng dụng có cần kết nối internet không?","faq.q5":"Dữ liệu của tôi có riêng tư không?","faq.q6":"Tại sao tải mô hình chậm?","faq.q7":"Thiết bị nào hoạt động tốt nhất?","faq.q8":"Tôi có thể tải mô hình GGUF tùy chỉnh không?","faq.q9":"Tôi có thể thay đổi nơi lưu trữ mô hình không?","faq.sub":"Vẫn bí? Mở issue trên GitHub hoặc liên hệ trực tiếp.","faq.title":"Những câu hỏi bạn có<br/>trước khi hỏi.","features.lead":"Trò chuyện, thị giác, tài liệu, giọng nói và công cụ — <b>tất cả chạy trên con chip trong túi bạn.</b>","features.title":"Mọi thứ bạn mong đợi.<br/>Không gì rời khỏi máy.","flow.a1":"15% của 240 là <b>36</b>.","flow.a3":"Cuộc họp thứ Năm dời sang thứ Sáu lúc 10 giờ sáng.","flow.a4":"Không — 391 = <b>17 × 23</b>.","flow.q1":"15% của 240 là bao nhiêu?","flow.q2":"Dịch “hẹn gặp lại ngày mai” sang tiếng Nhật.","flow.q3":"Tóm tắt email này trong một dòng.","flow.q4":"391 có phải là số nguyên tố không?","footer.about":"Ứng dụng mã nguồn mở để chạy các mô hình ngôn ngữ lớn ngay trên iPhone và iPad (sắp ra mắt) cùng Android. Xây dựng trên <a href=\"https://github.com/ggml-org/llama.cpp\">llama.cpp</a>. Giấy phép MIT.","footer.build":"Phát triển","footer.build.issues":"Trình theo dõi vấn đề","footer.build.releases":"Phát hành","footer.contact":"Liên hệ","footer.privacy":"Chính sách Bảo mật","footer.product":"Sản phẩm","footer.product.models":"Tất cả mô hình","hero.cta.android":"Tải trên Google Play","hero.cta.ios":"App Store · Sắp ra mắt","hero.lead":"Chạy các mô hình ngôn ngữ lớn <b>hoàn toàn ngoại tuyến</b>. Không đám mây, không tài khoản, không theo dõi — miễn phí và mã nguồn mở.","hero.note":"iPhone 15 Pro+ và iPad M1+ · Android 11+ · Giấy phép MIT","hero.publishers":"Chạy các mô hình trọng số mở từ","hero.title":"AI riêng tư.<br/>Ngay trên điện thoại của bạn.","how.dl.choose":"Chọn mô hình","how.dl.downloading":"Đang tải xuống · Wi‑Fi","how.dl.eta":"{speed} MB/s · còn {time}","how.dl.ready":"✓ Sẵn sàng trò chuyện","how.dl.saved":"Đã lưu trên thiết bị","how.dl.wait":"Đang chờ…","how.dl.waiting":"Đang chờ bạn chạm","how.eyebrow":"Cách hoạt động","how.lead":"Chạm vào một mô hình để thử — <b>hoặc chỉ cần xem.</b>","how.s1.body":"Chọn từ 40 mô hình mở, hoặc dùng GGUF của riêng bạn.","how.s1.title":"Chọn mô hình","how.s2.body":"Tải xuống trong nền, có hiển thị tiến độ và tự động tiếp tục.","how.s2.title":"Tải một lần","how.s3.body":"Suy luận hiển thị ngay trong cuộc trò chuyện. Lịch sử luôn nằm trên thiết bị của bạn.","how.s3.title":"Trò chuyện ngoại tuyến","how.title":"Ba lần chạm đến<br/>token đầu tiên.","lang.body":"Toàn bộ ứng dụng được dịch sang 28 ngôn ngữ, và ở lần mở đầu tiên, ứng dụng sẽ gợi ý một mô hình nói được ngôn ngữ của bạn. <a class=\"link\" href=\"https://github.com/andriydruk/LMPlayground\">Cải thiện bản dịch</a>","lang.eyebrow":"Ngôn ngữ","lang.title":"Nói ngôn ngữ của bạn.","meta.title":"LM Playground — AI riêng tư trên điện thoại của bạn","models.browse":"Xem tất cả mô hình","models.byo":"Cần một mô hình cụ thể? <b>Dùng GGUF của riêng bạn</b> — ứng dụng đọc mẫu trò chuyện ngay từ tệp.","models.eyebrow":"Mô hình","models.lead":"Mô hình là AI đứng sau cuộc trò chuyện — <b>một tệp duy nhất, chỉ tải một lần.</b> Mô hình càng lớn càng biết nhiều và suy luận tốt hơn, nhưng cần nhiều bộ nhớ hơn. Chọn dung lượng RAM của điện thoại để xem các mô hình phù hợp.","models.ram.note":"Gợi ý là những mô hình được tải nhiều nhất mà máy chạy được. iPhone 15 Pro trở lên có 8 GB; trên Android, xem trong Cài đặt → Giới thiệu về điện thoại.","models.ram.q":"Điện thoại của bạn có bao nhiêu RAM?","models.title":"Tìm bộ não phù hợp<br/>cho điện thoại của bạn.","mp.byo.android":"Đặt tệp .gguf vào thư mục đã chọn trong Cài đặt → Mô hình. Tệp sẽ hiện ngay cạnh các mô hình có sẵn.","mp.byo.body":"Mẫu trò chuyện và tokenizer được đọc trực tiếp từ tệp, nên hầu hết mô hình GGUF đều chạy ngay. Nếu có mô hình không chạy, <a class=\"link\" href=\"https://github.com/andriydruk/LMPlayground/issues\">hãy báo cho chúng tôi trên GitHub</a>","mp.byo.chat":"Chọn nó trong bộ chọn mô hình như mọi mô hình khác.","mp.byo.chat.title":"Bắt đầu trò chuyện","mp.byo.eyebrow":"Mô hình của riêng bạn","mp.byo.ios":"Chạm Nhập trong Cài đặt → Mô hình, hoặc sao chép tệp vào thư mục Models của ứng dụng trong Tệp.","mp.byo.ios.title":"iPhone và iPad","mp.byo.title":"Không thấy mô hình yêu thích?<br/>Tải bất kỳ GGUF nào.","mp.count.models":"mô hình","mp.count.publishers":"nhà phát hành","mp.count.tools":"dùng được công cụ","mp.count.vision":"xem được ảnh","mp.downloads":"{n} lượt tải / tháng","mp.empty":"Không có mô hình phù hợp. Hãy thử bộ lọc khác — hoặc dùng GGUF của riêng bạn.","mp.f.all":"Tất cả","mp.f.new":"Mới","mp.f.small":"Dưới 1 GB","mp.lead":"Các mô hình mở được chọn lọc và tinh chỉnh cho điện thoại. <b>Mỗi mô hình chạy hoàn toàn trên thiết bị của bạn</b> — tải một lần là dùng ngoại tuyến mãi về sau.","mp.meta.title":"Mô hình — LM Playground","mp.search":"Tìm mô hình","mp.shown.all":"Hiển thị tất cả {n} mô hình","mp.shown.some":"Hiển thị {n} trên {total} mô hình","mp.sort":"Sắp xếp mô hình","mp.sort.large":"Lớn nhất trước","mp.sort.name":"Tên","mp.sort.new":"Mới nhất trước","mp.sort.popular":"Phổ biến nhất","mp.sort.small":"Nhỏ nhất trước","mp.source":"Lượt tải là số lượt tải các tệp GGUF của từng mô hình trên Hugging Face trong 30 ngày qua (kiểm tra ngày 21 tháng 11, 2026).","mp.title":"Mọi mô hình.<br/>Chỉ một lần chạm.","nav.download":"Tải xuống","nav.faq":"Câu hỏi thường gặp","nav.features":"Tính năng","nav.how":"Cách hoạt động","nav.models":"Mô hình","nav.privacy":"Quyền riêng tư","phone.a":"Học máy là một nhánh của trí tuệ nhân tạo, trong đó máy tính **học từ dữ liệu** thay vì được lập trình rõ ràng.\n\nCác khái niệm chính:\n\n• **Huấn luyện**: cung cấp dữ liệu cho thuật toán\n• **Mô hình**: các mẫu học được từ dữ liệu\n• **Suy luận**: đưa ra dự đoán trên dữ liệu mới","phone.a1":"Với lãi kép 4% mỗi năm, $5,000 sẽ tăng lên **$7,401.22** sau 10 năm — tức là 5,000 × 1.04^10. Vậy bạn sẽ kiếm được khoảng **$2,401** tiền lãi cộng thêm vào số vốn gốc $5,000 của mình.","phone.a2":"Các nhà đánh giá phần lớn tích cực. Điểm cộng: **màn hình 3000-nit** sáng hơn nhiều, thời lượng pin tốt hơn khoảng **20%**, camera telephoto sắc nét hơn, cùng với AI chạy trực tiếp trên thiết bị nhanh hơn. Điểm chê chính là **giá khởi điểm cao hơn** — nhưng đa số vẫn gọi đây là chiếc Pixel tốt nhất từ trước đến nay.","phone.a3":"Karpathy đề xuất một **wiki do LLM duy trì** — một lớp markdown bền vững, liên kết chéo mà mô hình xây dựng giữa bạn và các nguồn gốc của bạn. Thay vì đọc lại mọi thứ cho mỗi truy vấn, nó cập nhật các trang và liên kết khi có tài liệu mới, để cơ sở kiến thức của bạn **tích lũy** thay vì phải dựng lại từ đầu mỗi lần.","phone.aD":"Bạn có thể chấm dứt hợp đồng với **thông báo bằng văn bản trước 60 ngày** sau thời hạn sáu tháng đầu. Tiền đặt cọc được hoàn lại trong vòng **14 ngày** kể từ khi dọn đi (Điều 8.2).","phone.aV":"Một con **cừu** với bộ lông trắng ngà dày và xoăn, đang cúi đầu gặm cỏ trên sườn đồi xanh mướt. Bầu trời âm u và đồng cỏ nhiều đá gợi lên một vùng cao nguyên mát mẻ.","phone.input":"Tin nhắn","phone.q":"Học máy là gì?","phone.q1":"Nếu tôi đầu tư $5,000 với lãi suất 4% mỗi năm, sau 10 năm nó sẽ có giá trị bao nhiêu?","phone.q2":"Các nhà đánh giá đang nói gì về chiếc Pixel mới nhất?","phone.q3":"Tóm tắt bài viết này: https://gist.github.com/karpathy/442a6bf555914893e9891c11519de94f","phone.qD":"Khi nào tôi có thể chấm dứt hợp đồng thuê nhà?","phone.qV":"Con vật trong bức ảnh này là gì?","phone.r0":"Người dùng muốn một định nghĩa đơn giản. Hãy nói về việc học từ dữ liệu so với các quy tắc tường minh, rồi đến các bước cốt lõi: huấn luyện, mô hình và suy luận. Giữ cho dễ hiểu với người mới bắt đầu.","phone.r1":"Giá trị tương lai với lãi kép: FV = P(1 + r)^n, với P = 5000, r = 0.04, n = 10. 1.04^10 vào khoảng 1.4802, nên FV vào khoảng 7401.22. Lãi = FV − P, vào khoảng 2401.","phone.r2":"Các kết quả đều thống nhất về sự cải thiện của màn hình, pin và camera, cùng với AI trên thiết bị nhanh hơn. Điểm tiêu cực lặp lại là mức giá cao hơn. Hãy tóm tắt thành lời khen so với nhược điểm chính.","phone.r3":"Karpathy đề xuất một wiki cá nhân do LLM duy trì. Ba lớp: nguồn gốc bất biến, một wiki do LLM tạo ra, và một tệp lược đồ. Mô hình cập nhật các trang và liên kết chéo khi có nguồn mới, nên kiến thức tích lũy dần. Hãy tóm tắt ý tưởng và cách phân lớp.","phone.rD":"Các đoạn trích cho biết hợp đồng thuê có thể chấm dứt sau thời hạn sáu tháng đầu với thông báo bằng văn bản trước 60 ngày, và Điều 8.2 quy định về tiền cọc: hoàn lại trong vòng 14 ngày kể từ khi dọn đi. Trả lời cả hai ý.","phone.rV":"Người dùng muốn tôi xác định con vật trong ảnh. Đó là một con cừu lông xù đang cúi đầu gặm cỏ trên sườn đồi xanh. Hãy trả lời ngắn gọn và nêu các đặc điểm chính của nó.","phone.send":"Gửi","phone.tD":"Đang tìm trong tài liệu","phone.thinking":"Đang suy nghĩ","priv.airplane":"Chế độ máy bay","priv.body1":"<b>Tháo SIM. Tắt Wi‑Fi. Vẫn trò chuyện.</b> Khi đã tải mô hình về, mọi suy luận đều diễn ra ngay trên điện thoại của bạn — trên máy bay, dưới tàu điện ngầm, ở bất cứ đâu.","priv.body2":"Không tài khoản, không khóa API, không đo lường từ xa, không phân tích dữ liệu. Công cụ web là tùy chọn và mặc định tắt.","priv.eyebrow":"Quyền riêng tư","priv.legend.net":"Lưu lượng mạng","priv.legend.tokens":"Token trên điện thoại của bạn","priv.link":"Đọc chính sách bảo mật","priv.sent":"gửi qua mạng","priv.title":"Riêng tư ngay từ thiết kế.","priv.tokens":"token đã tạo","priv.wifi":"Đã tắt Wi‑Fi","privacy.date":"Ngày hiệu lực: 2 tháng 6, 2026","privacy.intro":"Chào mừng bạn đến với LM Playground! Tôi cam kết duy trì niềm tin và sự tín nhiệm của mọi người dùng ứng dụng của tôi. Chính sách Bảo mật này giải thích những gì ứng dụng có và không thu thập, cách các cuộc trò chuyện của bạn được giữ trên thiết bị, và một vài trường hợp — chẳng hạn như các công cụ web tùy chọn — khi thông tin rời khỏi thiết bị của bạn, để bạn luôn biết điều gì sẽ xảy ra.","privacy.s1.body":"Tôi, Andriy Druk, nhà phát triển của LM Playground, không thu thập, lưu trữ, sử dụng hoặc chia sẻ bất kỳ thông tin cá nhân nào từ người dùng ứng dụng của tôi. Không có tài khoản, không có quảng cáo, và không có phân tích hay theo dõi sử dụng. Ứng dụng được thiết kế với quyền riêng tư của bạn là ưu tiên, để bạn có thể sử dụng mà không ảnh hưởng đến dữ liệu cá nhân của mình.","privacy.s1.title":"1. Không Thu thập Thông tin Cá nhân","privacy.s2.body":"Các cuộc trò chuyện, lời nhắc hệ thống và phản hồi của mô hình được xử lý cục bộ ngay trên thiết bị của bạn bởi mô hình chạy trên thiết bị. Nội dung này không bao giờ được gửi đến tôi hoặc đến bất kỳ máy chủ nào để suy luận. Nó vẫn nằm trên thiết bị của bạn trừ khi bạn chọn sử dụng một tính năng truy cập internet, như mô tả bên dưới.","privacy.s2.title":"2. Xử lý trên Thiết bị","privacy.s3.body":"LM Playground kết nối internet cho hai mục đích: tải xuống các tệp mô hình bạn chọn và — chỉ khi bạn bật — vận hành các công cụ web tùy chọn. Ứng dụng không có quảng cáo, đo từ xa hay phân tích sử dụng, và không báo cáo hoạt động của bạn cho tôi.","privacy.s3.title":"3. Truy cập Internet","privacy.s4.body":"Các mô hình đủ khả năng có thể dùng các công cụ tùy chọn, vốn được tắt theo mặc định. Khi bạn bật các công cụ web, một số thông tin sẽ rời khỏi thiết bị của bạn: công cụ Tìm kiếm web gửi truy vấn tìm kiếm của mô hình đến DuckDuckGo, và công cụ Tải trang web tải xuống các trang mà mô hình quyết định mở từ những trang web đó. Những yêu cầu đó được xử lý bởi các trang của bên thứ ba theo chính sách bảo mật riêng của họ — tôi không nhận cũng không lưu trữ chúng. Công cụ Chạy JavaScript chạy hoàn toàn trên thiết bị của bạn trong một môi trường cách ly không có truy cập internet. Để giữ mọi thứ ngoại tuyến, chỉ cần để các công cụ ở trạng thái tắt.","privacy.s4.title":"4. Công cụ và Truy cập Web","privacy.s5.body":"Với tư cách là nhà phát triển của LM Playground, tôi có quyền cập nhật Chính sách Bảo mật này bất cứ lúc nào. Bất kỳ thay đổi nào sẽ có hiệu lực ngay lập tức sau khi chính sách cập nhật được đăng. Người dùng được khuyến khích thường xuyên xem lại trang này và cập nhật về cách quyền riêng tư của mình được bảo vệ.","privacy.s5.title":"5. Cập nhật Chính sách Bảo mật","privacy.s6.body":"Bằng việc sử dụng LM Playground, bạn xác nhận và đồng ý với Chính sách Bảo mật này. Nếu bạn không đồng ý với chính sách, vui lòng ngừng sử dụng ứng dụng. Việc bạn tiếp tục sử dụng ứng dụng sau khi đăng bất kỳ cập nhật hoặc thay đổi nào đối với chính sách này sẽ được coi là bạn chấp nhận những thay đổi đó.","privacy.s6.title":"6. Chấp nhận Chính sách này","privacy.s7.body":"Nếu bạn có bất kỳ câu hỏi hoặc đề xuất nào về Chính sách Bảo mật của tôi, đừng ngần ngại liên hệ với tôi.","privacy.s7.title":"7. Liên hệ với tôi","privacy.title":"Chính sách Bảo mật","prompts.new":"Lời nhắc hệ thống mới","qa.stuck":"Vẫn còn vướng mắc? <a class=\"link\" href=\"https://github.com/andriydruk/LMPlayground/issues\">Mở issue trên GitHub</a>","qa.title":"Có câu hỏi?<br/>Có lời đáp.","store.android.small":"TẢI NỘI DUNG TRÊN","store.ios.small":"SẮP CÓ TRÊN","tools.t1.title":"Chạy JavaScript","tools.t2.title":"Tìm kiếm web","tools.t3.title":"Tải trang web","tp.balanced":"Cân bằng","tp.context":"Ngữ cảnh 4.096","tp.creative":"Sáng tạo","tp.focused":"Tập trung","tp.o1":"Xanh Đại Dương.","tp.o2":"Sương Bến Cảng — sắc xanh xám dịu mát.","tp.o3":"Vườn Cây Nửa Đêm: tím mận đậm thoáng chút xanh lục.","tp.o4":"Oải Hương Giông Bão, lấm tấm ánh đồng như mưa rơi trên mái tôn.","tp.o5":"Nhung Nhiễu Sóng — màu tiếng rè rè của chiếc radio lúc 3 giờ sáng khi chẳng ai nghe.","tp.precise":"Chính xác","tp.q":"Đặt tên cho một màu sơn mới.","tp.repeat":"Phạt lặp lại 1,1","tp.seed":"Hạt giống","tp.surprising":"Bất ngờ","tp.temperature":"Nhiệt độ","tp.wild":"Phá cách","ui.next":"Tiếp","ui.prev":"Trước","ui.theme":"Chuyển giao diện sáng hoặc tối","units.tokens":"%d token","why.devices.body":"iPhone 15 Pro trở lên và iPad M1 sắp được hỗ trợ. Android 11 trở lên đã dùng được ngay hôm nay.","why.devices.ipad":"iPad · sắp có","why.devices.iphone":"iPhone · sắp có","why.devices.title":"iPhone, iPad và Android.","why.engine.body":"Bộ máy mã nguồn mở đứng sau AI cục bộ. Dùng bất kỳ tệp GGUF nào và nó chạy ngay.","why.engine.title":"Vận hành bởi llama.cpp.","why.free.body":"Không thuê bao, không tài khoản, không quảng cáo. Mọi dòng code đều có trên GitHub.","why.free.title":"Miễn phí. Mãi mãi.","why.size.body":"Bốn mươi mô hình mở, từ những mô hình tí hon chạy trên mọi điện thoại đến những gã khổng lồ suy luận cho máy cao cấp. Mỗi chấm bên dưới là một mô hình bạn có thể tải xuống.","why.size.title":"Từ 267 MB đến 12 GB.","why.speed.body":"Tăng tốc GPU với Metal trên iPhone và iPad, và Vulkan trên Android.","why.speed.title":"Câu trả lời hiện ra ngay khi nó đang nghĩ.","why.title":"Đủ nhỏ để bỏ túi.<br/>Đủ thông minh để hữu ích."};
